"""Portable syntax, metadata-binding and real filesystem receiving controls."""

import base64
import copy
import hashlib
import json
import os
import tempfile
import unittest
import zlib
from pathlib import Path
from unittest.mock import patch

from signed_worker_acceptance_controls import receiver as r

PACK = {
    "historical_source_successor_review": "",
    "successor_expansion_review": "",
    "native_result": "",
    "native_admission": "",
    "current_admission_verification": "",
    "signed_manifest": "",
    "raw_public_worker_artifact": "",
    "decoded_public_worker_artifact": "",
    "public_worker_context": "",
    "authored_worker_receipt": "",
    "execution_scope_before": "",
    "execution_scope_after_stop": "",
    "native_lifecycle": "",
    "worker_candidate": "",
    "prerequisite_claim": "",
    "prerequisite_validation": "",
    "published_public_checks": "",
    "published_source_receipt": "",
    "container_boundary": "",
    "worker_stdout_log": "",
}
RAW = {role: zlib.decompress(base64.b64decode(value)) for role, value in PACK.items()}
DOCS = {role: r.document(raw) for role, raw in RAW.items() if role != "worker_stdout_log"}
DOCS["worker_boundary_receipt"], DOCS["worker_output_receipt"] = r.worker_log(
    RAW["worker_stdout_log"]
)


def wire(value):
    return (
        json.dumps(value, sort_keys=True, indent=2, ensure_ascii=True, allow_nan=False) + "\n"
    ).encode("ascii")


def replace_strings(value, before, after):
    if type(value) is dict:
        return {key: replace_strings(child, before, after) for key, child in value.items()}
    if type(value) is list:
        return [replace_strings(child, before, after) for child in value]
    return value.replace(before, after) if type(value) is str else value


def repaired(docs):
    """Independently repair transport hashes without repairing the tested predicates."""
    old = docs["public_worker_context"]["sha256"]
    public_raw = wire(docs["raw_public_worker_artifact"])
    new = hashlib.sha256(public_raw).hexdigest()
    docs = replace_strings(docs, old, new)
    authored = docs["authored_worker_receipt"]
    authored["original_artifact"]["bytes"] = len(public_raw)
    authored["actual_boundary_stdout_observation"]["receipt"] = copy.deepcopy(
        docs["worker_boundary_receipt"]
    )
    authored["actual_stdout_observation"]["receipt"] = copy.deepcopy(docs["worker_output_receipt"])
    lines = RAW["worker_stdout_log"].decode("utf-8").splitlines()
    lines[8] = json.dumps(docs["worker_boundary_receipt"], sort_keys=True)
    lines[9] = json.dumps(docs["worker_output_receipt"], sort_keys=True)
    log = ("\n".join(lines) + "\n").encode("utf-8")
    for key in ("actual_boundary_stdout_observation", "actual_stdout_observation"):
        authored[key]["log"]["sha256"] = hashlib.sha256(log).hexdigest()
        authored[key]["log"]["bytes"] = len(log)
    docs["native_result"]["authored_worker_receipt"] = copy.deepcopy(authored)
    bodies = {role: wire(docs[role]) for role in r.ROLES if role != "worker_stdout_log"}
    bodies["container_boundary"] = RAW["container_boundary"]
    bodies["worker_stdout_log"] = log
    review = docs["successor_expansion_review"]["signed_worker"]
    review["native_result"]["sha256"] = hashlib.sha256(bodies["native_result"]).hexdigest()
    review["native_result"]["bytes"] = len(bodies["native_result"])
    bodies["successor_expansion_review"] = wire(docs["successor_expansion_review"])
    return docs, {role: hashlib.sha256(body).hexdigest() for role, body in bodies.items()}, bodies


class MetadataControls(unittest.TestCase):
    def setUp(self):
        self.docs = copy.deepcopy(DOCS)

    def refusal(self, phrase):
        docs, pins, bodies = repaired(self.docs)
        with self.assertRaisesRegex(r.Refusal, phrase):
            r.reconcile(docs, pins, bodies)

    def test_original_and_independently_reencoded_positive(self):
        first = r.reconcile(copy.deepcopy(DOCS), {k: r.sha(v) for k, v in RAW.items()}, RAW)
        docs, pins, bodies = repaired(self.docs)
        second = r.reconcile(docs, pins, bodies)
        self.assertEqual(
            first["admission"]["administrator_task_cids"],
            second["admission"]["administrator_task_cids"],
        )
        self.assertEqual(second["completion"]["prelaunch_task_statuses"], ["completed", "ready"])
        self.assertFalse(second["admission"]["signatures_authenticated_here"])

    def test_historical_unsigned_scope_cannot_be_rewritten(self):
        self.docs["historical_source_successor_review"]["signed_successor_worker_qualified"] = True
        self.refusal("historical unsigned successor scope")

    def test_completed_signed_milestone_cannot_be_downgraded(self):
        self.docs["successor_expansion_review"]["signed_successor_dispatch_qualified"] = False
        self.refusal("later completed signed milestone")

    def test_recorded_proof_promotion_refused_after_hash_repair(self):
        self.docs["native_result"]["proof_authority"] = True
        self.refusal("native record limited scope")

    def test_main_zero_boolean_alias_refused(self):
        self.docs["native_result"]["new_fitting_epochs"] = False
        self.refusal("exact scalar type")

    def test_nested_zero_boolean_alias_refused(self):
        self.docs["worker_output_receipt"]["provider_calls"] = False
        self.refusal("exact scalar type")

    def test_unknown_main_field_refused(self):
        self.docs["native_result"]["new_authority"] = False
        self.refusal("closed fields")

    def test_unknown_nested_field_refused(self):
        self.docs["signed_manifest"]["binding"]["future_authority"] = False
        self.refusal("closed fields")

    def test_future_public_schema_refused(self):
        for key in ("raw_public_worker_artifact", "decoded_public_worker_artifact"):
            self.docs[key]["schema"] = "supervisor-public-instruction@5"
        self.refusal("closed current public schemas")

    def test_native_and_public_admission_shapes_stay_distinct(self):
        for key in ("raw_public_worker_artifact", "decoded_public_worker_artifact"):
            self.docs[key]["inventory_plan_admission"]["manifest"] = copy.deepcopy(
                self.docs["signed_manifest"]
            )
        self.refusal("closed fields")

    def test_raw_decoded_projection_transplant_refused(self):
        self.docs["decoded_public_worker_artifact"]["task_id"] = "SUCCESSOR-TYPE"
        self.refusal("raw and decoded public artifact complete equality")

    def test_signature_encoding_refused_without_crypto(self):
        for body in (
            self.docs["signed_manifest"],
            self.docs["native_admission"]["manifest"],
            self.docs["raw_public_worker_artifact"]["manifest"],
            self.docs["decoded_public_worker_artifact"]["manifest"],
        ):
            body["binding"]["signature"] = "broken-signature"
        self.refusal("signature encoding")

    def test_complete_original_tasks_cannot_be_omitted(self):
        self.docs["native_admission"]["graph"]["tasks"].pop()
        self.refusal("closed list length")

    def test_mandatory_evidence_cannot_be_made_optional(self):
        self.docs["native_admission"]["receipt"]["payload"]["pending_requirements"][0][
            "required"
        ] = False
        for role in ("raw_public_worker_artifact", "decoded_public_worker_artifact"):
            self.docs[role]["inventory_plan_admission"]["receipt"] = copy.deepcopy(
                self.docs["native_admission"]["receipt"]
            )
        self.refusal("unchanged mandatory evidence phase/ceiling")

    def test_prelaunch_residual_does_not_repeat_completed_type(self):
        for role in ("execution_scope_before", "execution_scope_after_stop"):
            self.docs[role]["payload"]["native_population"]["selected_task_cids"].insert(
                0, self.docs["native_admission"]["graph"]["tasks"][0]["content_id"]
            )
        self.refusal("closed list length")

    def test_worker_cannot_claim_native_completion(self):
        self.docs["worker_output_receipt"]["native_completion_recorded_here"] = True
        self.refusal("worker edits without self-completion authority")

    def test_public_signature_claim_is_preserved_as_declaration(self):
        self.docs["authored_worker_receipt"]["public_signatures_verified"] = False
        self.refusal("historical receipt verification declarations")

    def test_worker_private_read_promotion_refused(self):
        key = next(iter(self.docs["worker_boundary_receipt"]["private_access"]))
        self.docs["worker_boundary_receipt"]["private_access"][key]["read"] = True
        self.refusal("recorded private denial only")

    def test_worker_self_approval_refused_after_container_hash_repair(self):
        for role in ("native_result", "native_lifecycle"):
            receipt = self.docs[role]["residual_task"]["body"]["completion_receipt"]
            receipt["validation"]["accepted_source_transition"]["worker_self_approval"] = True
            receipt["coordination_preparation"]["body"]["validation"]["accepted_source_transition"][
                "worker_self_approval"
            ] = True
        self.refusal("accepted source transition no worker authority")

    def test_exact_stale_type_cannot_be_generic_valueerror(self):
        self.docs["native_result"]["controls"][0]["error_type"] = "ValueError"
        self.refusal("exact typed stale-head observation")

    def test_timeout_cannot_be_rebranded_integrity_refusal(self):
        self.docs["native_result"]["public_receivers_reference_close"][
            "integrity_refusal_claimed"
        ] = True
        self.docs["successor_expansion_review"]["signed_worker"]["reference_close"][
            "integrity_refusal_claimed"
        ] = True
        self.refusal("reference timeout is not completed baseline or integrity refusal")

    def test_public_check_output_digest_independently_rederived(self):
        for rows in (
            self.docs["published_public_checks"],
            self.docs["native_result"]["publication"]["public_checks"],
            self.docs["successor_expansion_review"]["signed_worker"]["publication"][
                "public_checks"
            ],
        ):
            rows[0]["stdout_sha256"] = "a" * 64
        self.refusal("public check output bytes/digest")

    def test_two_parent_merge_binding_refused(self):
        self.docs["native_result"]["publication"]["parents"][1] = "b" * 40
        self.docs["successor_expansion_review"]["signed_worker"]["publication"]["parents"][1] = (
            "b" * 40
        )
        self.refusal("two-parent merge/transition binding")

    def test_generation_three_declaration_cannot_be_four(self):
        self.docs["published_source_receipt"]["generation"] = 4
        self.refusal("declared generation2 to3 publication")


class FileControls(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="signed-worker-acceptance-")
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.inputs = self.root / "inputs"
        self.inputs.mkdir()
        self.output = self.root / "out"
        self.rows = []
        for index, role in enumerate(r.ROLES):
            body = RAW[role]
            path = self.inputs / f"{index:02d}.body"
            path.write_bytes(body)
            self.rows.append(
                {"role": role, "path": str(path), "sha256": r.sha(body), "size_bytes": len(body)}
            )
        self.manifest = self.inputs / "manifest.json"
        self.write_manifest()

    def write_manifest(self, **extra):
        self.manifest.write_bytes(
            wire({"schema": r.INPUT_SCHEMA, "selected_files": self.rows, **extra})
        )

    def run_receiver(self):
        return r.audit(self.manifest, self.output)

    def test_actual_portable_receive_typed_scope_and_retained_bytes(self):
        report = self.run_receiver()
        self.assertIs(report["qualified"], True)
        for key in r.TRUE:
            self.assertIs(report[key], True)
        for key in r.FALSE:
            self.assertIs(report[key], False)
        for key in r.ZERO:
            self.assertIs(type(report[key]), int)
            self.assertEqual(report[key], 0)
        self.assertEqual(report["selected_file_count"], 20)
        self.assertEqual(report["selected_input_bytes"], 5987964)
        self.assertEqual(report["custody"]["closing_raw_body_count"], 43)
        for row in report["selected_files"]:
            self.assertEqual(Path(row["retained_copy"]["path"]).read_bytes(), RAW[row["role"]])
        self.assertEqual(len(list(self.output.rglob("*.body"))), 20)
        self.assertEqual(r.document((self.output / r.REPORT_NAME).read_bytes()), report)

    def test_ordered_manifest_and_main_schema_are_closed(self):
        self.write_manifest(extra=False)
        with self.assertRaisesRegex(r.Refusal, "closed fields"):
            self.run_receiver()

    def test_manifest_selector_order_cannot_change(self):
        self.rows[0], self.rows[1] = self.rows[1], self.rows[0]
        self.write_manifest()
        with self.assertRaisesRegex(r.Refusal, "typed ordered descriptor"):
            self.run_receiver()

    def test_descriptor_boolean_size_refused(self):
        self.rows[0]["size_bytes"] = True
        self.write_manifest()
        with self.assertRaisesRegex(r.Refusal, "typed ordered descriptor"):
            self.run_receiver()

    def test_alias_symlink_refused(self):
        path = Path(self.rows[0]["path"])
        other = self.inputs / "alias-target"
        path.rename(other)
        path.symlink_to(other)
        with self.assertRaisesRegex(r.Refusal, "canonical selected path"):
            self.run_receiver()

    def test_physical_alias_refused_even_for_equal_scope_bodies(self):
        path = Path(self.rows[11]["path"])
        path.unlink()
        os.link(Path(self.rows[10]["path"]), path)
        with self.assertRaisesRegex(r.Refusal, "physical aliases"):
            self.run_receiver()

    def test_nonregular_fifo_refused_without_blocking(self):
        path = Path(self.rows[0]["path"])
        path.unlink()
        os.mkfifo(path)
        with self.assertRaisesRegex(r.Refusal, "regular selected body"):
            self.run_receiver()

    def test_original_descriptor_hash_drift_refused(self):
        path = Path(self.rows[0]["path"])
        path.write_bytes(path.read_bytes() + b" ")
        with self.assertRaisesRegex(r.Refusal, "exact selected raw descriptor"):
            self.run_receiver()

    def test_total_bound_applies_before_large_body_allocation(self):
        with (
            patch.object(r, "MAX_TOTAL", 1024),
            self.assertRaisesRegex(r.Refusal, "regular selected body/cap"),
        ):
            self.run_receiver()

    def test_file_population_bound_applies_during_capture(self):
        with (
            patch.object(r, "MAX_FILES", 3),
            self.assertRaisesRegex(r.Refusal, "file population cap"),
        ):
            self.run_receiver()

    def test_existing_output_refused(self):
        self.output.mkdir()
        with self.assertRaisesRegex(r.Refusal, "fresh output"):
            self.run_receiver()

    def late_semantic(self, mutate):
        original = r.reconcile

        def operation(*args):
            summary = original(*args)
            mutate()
            return summary

        with patch.object(r, "reconcile", operation), self.assertRaises(r.Refusal):
            self.run_receiver()

    def test_late_original_bytes_refused_after_metadata_checks(self):
        path = Path(self.rows[0]["path"])
        self.late_semantic(lambda: path.write_bytes(path.read_bytes() + b" "))

    def test_late_original_inode_replacement_refused_with_same_bytes(self):
        path = Path(self.rows[0]["path"])

        def mutation():
            replacement = self.root / "replacement"
            replacement.write_bytes(path.read_bytes())
            os.replace(replacement, path)

        self.late_semantic(mutation)

    def test_late_manifest_bytes_refused(self):
        self.late_semantic(lambda: self.manifest.write_bytes(self.manifest.read_bytes() + b" "))

    def test_late_input_directory_generation_refused(self):
        def mutation():
            old = self.root / "previous-inputs"
            self.inputs.rename(old)
            self.inputs.mkdir()
            for path in old.iterdir():
                path.rename(self.inputs / path.name)

        self.late_semantic(mutation)

    def late_publication(self, mutate, phrase=None):
        original = r.publish

        def publication(path, body):
            original(path, body)
            if path.name == r.REPORT_NAME:
                mutate(path)

        with patch.object(r, "publish", publication):
            if phrase:
                with self.assertRaisesRegex(r.Refusal, phrase):
                    self.run_receiver()
            else:
                with self.assertRaises(r.Refusal):
                    self.run_receiver()

    def test_late_retained_copy_bytes_refused(self):
        def mutation(_):
            path = self.output / "retained/00-historical_source_successor_review.body"
            path.write_bytes(path.read_bytes() + b" ")

        self.late_publication(mutation)

    def test_late_retained_manifest_bytes_refused(self):
        def mutation(_):
            path = self.output / "retained/input_manifest.json"
            path.write_bytes(path.read_bytes() + b" ")

        self.late_publication(mutation)

    def test_late_report_false_scope_promotion_refused(self):
        def mutation(path):
            value = r.document(path.read_bytes())
            value["signature_authentication_performed"] = True
            path.write_bytes(wire(value))

        self.late_publication(mutation, "published report bytes unchanged")

    def test_late_extra_output_file_refused(self):
        self.late_publication(
            lambda _: (self.output / "unselected.body").write_bytes(b"extra"),
            "unexpected output body",
        )

    def test_late_nested_output_directory_refused(self):
        self.late_publication(
            lambda _: (self.output / "retained/unselected").mkdir(), "unexpected output directory"
        )

    def test_late_output_directory_generation_refused(self):
        def mutation(_):
            old = self.root / "previous-output"
            self.output.rename(old)
            self.output.mkdir()
            for path in old.iterdir():
                path.rename(self.output / path.name)

        self.late_publication(mutation)


class SyntaxControls(unittest.TestCase):
    def test_strict_json_boundaries(self):
        for body, phrase in [
            (b'{"a":0,"a":1}', "duplicate"),
            (b'{"a":NaN}', "non-finite"),
            (b'{"a":Infinity}', "non-finite"),
            (b'{"a":"\\ud800"}', "surrogate"),
            (b'{"a":9223372036854775808}', "integer bound"),
            (b"\xff", "bounded JSON"),
            (b"[" * 33 + b"0" + b"]" * 33, "nesting bound"),
        ]:
            with self.subTest(body=body), self.assertRaisesRegex(r.Refusal, phrase):
                r.document(body)

    def test_value_population_bound(self):
        with self.assertRaisesRegex(r.Refusal, "value/depth bound"):
            r.document(b"[" + b",".join([b"0"] * 100000) + b"]")

    def test_worker_log_duplicate_or_relocated_record_refused(self):
        lines = RAW["worker_stdout_log"].splitlines()
        for forged in (
            b"\n".join(lines + [lines[9]]) + b"\n",
            b"prefix\n" + RAW["worker_stdout_log"],
        ):
            with (
                self.subTest(forged=len(forged)),
                self.assertRaisesRegex(r.Refusal, "receipt line positions"),
            ):
                r.worker_log(forged)

    def test_worker_log_invalid_utf8_refused(self):
        with self.assertRaisesRegex(r.Refusal, "bounded UTF8 worker log"):
            r.worker_log(b"\xff")


if __name__ == "__main__":
    unittest.main()
